const allRows = $input.all()
const body = $('Webhook Trigger').first().json.body || {}
const apiKey    = (body.apiKey || body.api_key || '').trim()
const keyword   = (body.keyword  || '').trim()
const location  = (body.location || '').trim()
const userEmail = (body.email    || '').trim()

const today = new Date().toISOString().split('T')[0]

if (!apiKey) {
  return [{ json: { allowed: false, reason: 'missing_key', userEmail, keyword, location, apiKey: '' } }]
}

const matchRow = allRows.find(r => (r.json.api_key || '').trim() === apiKey)
if (!matchRow) {
  return [{ json: { allowed: false, reason: 'invalid_key', userEmail, keyword, location, apiKey } }]
}

const row = matchRow.json
const isActive = (row.active || '').toString().toLowerCase().trim() === 'yes'
if (!isActive) {
  return [{ json: { allowed: false, reason: 'inactive_key', userEmail, keyword, location, apiKey } }]
}

const limit      = parseInt(row.daily_limit) || 5
const lastReset  = (row.last_reset || '').trim()
const isNewDay   = !lastReset || lastReset < today
const currentCnt = isNewDay ? 0 : parseInt(row.daily_count) || 0
const newCount   = currentCnt + 1

if (newCount > limit) {
  return [{ json: { allowed: false, reason: 'rate_limited', userEmail, keyword, location, apiKey, remaining: 0 } }]
}

return [{
  json: {
    allowed: true, apiKey, newCount, today, keyword, location, userEmail,
    remaining: limit - newCount
  }
}]

const names    = $json.first_name || []
const lasts    = $json.last_name || []
const titles   = $json.title || []
const orgs     = $json['organization.name'] || []
const emails   = $json.email || []

const ctx       = $('Validate & Check Rate Limit').first().json
const keyword   = ctx.keyword   || ''
const location  = ctx.location  || ''
const userEmail = ctx.userEmail || ''
const remaining = ctx.remaining !== undefined ? ctx.remaining : '?'

const subject = `Lead Generation Results: ${keyword} in ${location}`

if (emails.length === 0) {
  return { json: { toEmail: userEmail, subject,
    emailBody: `<html><body style="font-family:sans-serif;max-width:580px;margin:40px auto"><h2>Lead Generation Complete</h2><p><strong>Keyword:</strong> ${keyword}<br><strong>Location:</strong> ${location}</p><p>No verified contacts found. Try a broader keyword or location.</p><p style="color:#888">Requests remaining today: ${remaining}</p></body></html>`
  } }
}

const rows = emails.map((email, i) => `
  <tr>
    <td style="padding:6px 10px;border-bottom:1px solid #eee">${names[i] || ''} ${lasts[i] || ''}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #eee">${titles[i] || ''}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #eee">${orgs[i] || ''}</td>
    <td style="padding:6px 10px;border-bottom:1px solid #eee;font-family:monospace">${email}</td>
  </tr>`).join('')

return { json: { toEmail: userEmail, subject,
  emailBody: `<html><body style="font-family:sans-serif;max-width:720px;margin:40px auto"><h2>Lead Generation Results</h2><p><strong>Keyword:</strong> ${keyword} &nbsp;|&nbsp; <strong>Location:</strong> ${location} &nbsp;|&nbsp; <strong>Leads Found:</strong> ${emails.length}</p><table style="border-collapse:collapse;width:100%"><tr style="background:#f4f4f4"><th style="padding:6px 10px;text-align:left">Name</th><th style="padding:6px 10px;text-align:left">Title</th><th style="padding:6px 10px;text-align:left">Company</th><th style="padding:6px 10px;text-align:left">Email</th></tr>${rows}</table><p style="color:#888;margin-top:20px">Requests remaining today: ${remaining} of 5</p></body></html>`
} }
